CREATE DATABASE biblioteca_api
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

CREATE TABLE livros (
    id INT,
    titulo VARCHAR(200),
    autor VARCHAR(150),
    ano_publicacao INT
);

CREATE TABLE IF NOT EXISTS livros (
    id INT,
    titulo VARCHAR(200)
);

CREATE TABLE livros (
    id INT PRIMARY KEY,
    titulo VARCHAR(200),
    autor VARCHAR(150)
);

CREATE TABLE livros (
    id INT AUTO_INCREMENT PRIMARY KEY,
    titulo VARCHAR(200),
    autor VARCHAR(150)
);

DROP TABLE IF EXISTS livros;

CREATE TABLE livros (
    id INT AUTO_INCREMENT PRIMARY KEY,
    titulo VARCHAR(200) NOT NULL,
    autor VARCHAR(150),
    ano_publicacao SMALLINT,
    isbn CHAR(13) UNIQUE,
    preco DECIMAL(10,2) CHECK (preco >= 0),
    disponivel BOOLEAN DEFAULT TRUE
);

-- BETWEEN: pesquisa em um intervalo
SELECT * FROM livros WHERE preco BETWEEN 30 AND 50;

-- IN: pesquisa vários valores ao mesmo tempo
SELECT * FROM livros WHERE autor IN ('Machado de Assis', 'Jorge Amado');

-- LIKE: pesquisa por padrões de texto (% = qualquer sequência)
SELECT * FROM livros WHERE titulo LIKE 'Dom%';

-- IS NULL / IS NOT NULL: nunca use "= NULL"
SELECT * FROM livros WHERE isbn IS NULL;

SELECT * FROM livros
ORDER BY preco DESC
LIMIT 3;

SELECT autor, COUNT(*) AS QuantidadeLivros
FROM livros
GROUP BY autor;

CREATE TABLE autores (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(150)
);

CREATE TABLE livros (
    id INT AUTO_INCREMENT PRIMARY KEY,
    titulo VARCHAR(200),
    autor_id INT,
    FOREIGN KEY (autor_id) REFERENCES autores(id)
);

SELECT l.titulo, a.nome
FROM livros l
INNER JOIN autores a ON l.autor_id = a.id;

UPDATE livros
SET preco = 34.90
WHERE id = 2;
